window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e1744574d8081c05"]={"versions": [{"id": "FIG-e1744574d8081c05", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Ablauf- und Werkzeugkettendiagramm (Tool Chain / Workflow) zur AUTOSAR-Systembeschreibung und zum Modellaustausch zwischen OEM und Zulieferer (Supplier) gemäß AUTOSAR TR Interoperability of AUTOSAR Tools.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Organisationsdomänen / Swimlanes</strong>:</li>\n<li><code>OEM</code>: Umfasst die Systemerstellung, Systemerweiterung, Extraktion und Systemkonfiguration.</li>\n<li><code>Supplier</code>: Umfasst die Implementierung und Verfeinerung von Teilsystembeschreibungen.</li>\n<li><strong>Werkzeuge (Tools)</strong>:</li>\n<li><code>Authoring Tool 1</code>: Werkzeug zur initialen Modellgenerierung bei der OEM-Domäne.</li>\n<li><code>Authoring Tool 2</code>: Werkzeug zur Bearbeitung und Anreicherung der Systembeschreibung beim OEM.</li>\n<li><code>Extract Tool</code>: Werkzeug zur Erzeugung lieferantenspezifischer Systemauszüge beim OEM.</li>\n<li><code>Authoring Tool 3</code>: Werkzeug zur Implementierung und Verfeinerung beim Zulieferer.</li>\n<li><strong>Prozessschritte (Aktivitäten)</strong>:</li>\n<li><code>generate AUTOSAR model from existing data</code> (OEM)</li>\n<li><code>edit system description</code> (OEM)</li>\n<li><code>Configure System</code> (OEM)</li>\n<li><code>extract system description for supplier</code> (OEM)</li>\n<li><code>implement and refine system description</code> (Supplier)</li>\n<li><strong>Artefakte / Datenobjekte</strong>:</li>\n<li><code>existing data</code>: Nicht-AUTOSAR-Ausgangsdaten / Bestandsdaten.</li>\n<li><code>initial system description : System</code>: AUTOSAR-XML-Artefakt (.XML) nach Erstgenerierung.</li>\n<li><code>extended system description : System</code>: Angereichertes AUTOSAR-XML-Artefakt (.XML).</li>\n<li><code>extract from OEM ssystem description : System</code>: Auszug der Systembeschreibung (.XML) für den Zulieferer.</li>\n<li><code>refined system description : System</code>: Verfeinertes und zurückgeliefertes AUTOSAR-XML-Artefakt (.XML) des Zulieferers.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>Authoring Tool 1</code> transformiert <code>existing data</code> über die Aktivität <code>generate AUTOSAR model from existing data</code> in die <code>initial system description : System</code> (.XML).</li>\n<li><code>Authoring Tool 2</code> bearbeitet und ergänzt diese Datei im Schritt <code>edit system description</code>, woraus die <code>extended system description : System</code> (.XML) resultiert.</li>\n<li>Die <code>extended system description : System</code> wird im Schritt <code>extract system description for supplier</code> über das <code>Extract Tool</code> aufbereitet; daraus entsteht das Teilartefakt <code>extract from OEM ssystem description : System</code> (.XML).</li>\n<li>Das extrahierte XML-Artefakt wird an den <code>Supplier</code> übergeben.</li>\n<li>Der Zulieferer verarbeitet das Modell im Schritt <code>implement and refine system description</code> unter Nutzung von <code>Authoring Tool 3</code> und erstellt die <code>refined system description : System</code> (.XML).</li>\n<li>Die verfeinerte Systembeschreibung wird an den OEM zurückgeführt und fließt gemeinsam mit der Systemgesamtsicht in den OEM-Schritt <code>Configure System</code> ein.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert den standardisierten Roundtrip- bzw. Handover-Workflow für AUTOSAR-XML-Dateien (<code>ARXML</code>) über Organisationsgrenzen hinweg. Für die Interoperabilität ist sicherzustellen, dass Extraktionswerkzeuge (<code>Extract Tool</code>) semantisch und syntaktisch valide Teilmodelle des Typs <code>System</code> erzeugen und dass Autorentoolketten (<code>Authoring Tool 1–3</code>) konsistente XML-Schemata und Modellversionen gemäß den Spezifikationsvorgaben verwenden, um verlustfreie Modellzusammenführungen im Konfigurationsschritt zu gewährleisten.</p>"}, {"id": "FIG-26c52f7214886ea2", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Ablauf- und Werkzeugkettendiagramm (Tool Chain / Workflow) zur AUTOSAR-Systembeschreibung und zum Modellaustausch zwischen OEM und Zulieferer (Supplier) gemäß AUTOSAR TR Interoperability of AUTOSAR Tools.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Organisationsdomänen / Swimlanes</strong>:</li>\n<li><code>OEM</code>: Umfasst die Systemerstellung, Systemerweiterung, Extraktion und Systemkonfiguration.</li>\n<li><code>Supplier</code>: Umfasst die Implementierung und Verfeinerung von Teilsystembeschreibungen.</li>\n<li><strong>Werkzeuge (Tools)</strong>:</li>\n<li><code>Authoring Tool 1</code>: Werkzeug zur initialen Modellgenerierung bei der OEM-Domäne.</li>\n<li><code>Authoring Tool 2</code>: Werkzeug zur Bearbeitung und Anreicherung der Systembeschreibung beim OEM.</li>\n<li><code>Extract Tool</code>: Werkzeug zur Erzeugung lieferantenspezifischer Systemauszüge beim OEM.</li>\n<li><code>Authoring Tool 3</code>: Werkzeug zur Implementierung und Verfeinerung beim Zulieferer.</li>\n<li><strong>Prozessschritte (Aktivitäten)</strong>:</li>\n<li><code>generate AUTOSAR model from existing data</code> (OEM)</li>\n<li><code>edit system description</code> (OEM)</li>\n<li><code>Configure System</code> (OEM)</li>\n<li><code>extract system description for supplier</code> (OEM)</li>\n<li><code>implement and refine system description</code> (Supplier)</li>\n<li><strong>Artefakte / Datenobjekte</strong>:</li>\n<li><code>existing data</code>: Nicht-AUTOSAR-Ausgangsdaten / Bestandsdaten.</li>\n<li><code>initial system description : System</code>: AUTOSAR-XML-Artefakt (.XML) nach Erstgenerierung.</li>\n<li><code>extended system description : System</code>: Angereichertes AUTOSAR-XML-Artefakt (.XML).</li>\n<li><code>extract from OEM ssystem description : System</code>: Auszug der Systembeschreibung (.XML) für den Zulieferer.</li>\n<li><code>refined system description : System</code>: Verfeinertes und zurückgeliefertes AUTOSAR-XML-Artefakt (.XML) des Zulieferers.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>Authoring Tool 1</code> transformiert <code>existing data</code> über die Aktivität <code>generate AUTOSAR model from existing data</code> in die <code>initial system description : System</code> (.XML).</li>\n<li><code>Authoring Tool 2</code> bearbeitet und ergänzt diese Datei im Schritt <code>edit system description</code>, woraus die <code>extended system description : System</code> (.XML) resultiert.</li>\n<li>Die <code>extended system description : System</code> wird im Schritt <code>extract system description for supplier</code> über das <code>Extract Tool</code> aufbereitet; daraus entsteht das Teilartefakt <code>extract from OEM ssystem description : System</code> (.XML).</li>\n<li>Das extrahierte XML-Artefakt wird an den <code>Supplier</code> übergeben.</li>\n<li>Der Zulieferer verarbeitet das Modell im Schritt <code>implement and refine system description</code> unter Nutzung von <code>Authoring Tool 3</code> und erstellt die <code>refined system description : System</code> (.XML).</li>\n<li>Die verfeinerte Systembeschreibung wird an den OEM zurückgeführt und fließt gemeinsam mit der Systemgesamtsicht in den OEM-Schritt <code>Configure System</code> ein.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert den standardisierten Roundtrip- bzw. Handover-Workflow für AUTOSAR-XML-Dateien (<code>ARXML</code>) über Organisationsgrenzen hinweg. Für die Interoperabilität ist sicherzustellen, dass Extraktionswerkzeuge (<code>Extract Tool</code>) semantisch und syntaktisch valide Teilmodelle des Typs <code>System</code> erzeugen und dass Autorentoolketten (<code>Authoring Tool 1–3</code>) konsistente XML-Schemata und Modellversionen gemäß den Spezifikationsvorgaben verwenden, um verlustfreie Modellzusammenführungen im Konfigurationsschritt zu gewährleisten.</p>"}], "trans": [{"from": "FIG-e1744574d8081c05", "to": "FIG-26c52f7214886ea2", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
